
const express = require('express');
const mysql = require('mysql2/promise');
const cors = require('cors');

const app = express();

app.use(cors());
app.use(express.json());

const dbConfig = {
    host: 'localhost',
    user: 'root',
    password: '',
    database: 'crud_funcionarios'
};

const db = mysql.createPool(dbConfig);

// GET /api/funcionarios - Listar funcionários
app.get('/api/funcionarios', async (req, res) => {
    try {
        const [rows] = await db.execute(
            'SELECT * FROM funcionarios ORDER BY id DESC'
        );

        res.json(rows);
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// POST /api/funcionarios - Cadastrar funcionário
app.post('/api/funcionarios', async (req, res) => {
    try {
        const { nome, funcao, salario } = req.body;

        if (
            !nome?.trim() ||
            !funcao?.trim() ||
            salario === undefined ||
            salario === null ||
            salario === ''
        ) {
            return res.status(400).json({
                error: 'Todos os campos são obrigatórios.'
            });
        }

        const valorSalario = Number(salario);

        if (!Number.isFinite(valorSalario) || valorSalario < 0) {
            return res.status(400).json({
                error: 'O salário deve ser um número válido e não negativo.'
            });
        }

        const [result] = await db.execute(
            `INSERT INTO funcionarios (nome, funcao, salario)
             VALUES (?, ?, ?)`,
            [nome.trim(), funcao.trim(), valorSalario]
        );

        res.status(201).json({
            success: true,
            id: result.insertId
        });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// PUT /api/funcionarios/:id - Atualizar funcionário
app.put('/api/funcionarios/:id', async (req, res) => {
    try {
        const { nome, funcao, salario } = req.body;
        const id = Number(req.params.id);

        if (!Number.isInteger(id) || id <= 0) {
            return res.status(400).json({
                error: 'ID inválido.'
            });
        }

        if (
            !nome?.trim() ||
            !funcao?.trim() ||
            salario === undefined ||
            salario === null ||
            salario === ''
        ) {
            return res.status(400).json({
                error: 'Todos os campos são obrigatórios.'
            });
        }

        const valorSalario = Number(salario);

        if (!Number.isFinite(valorSalario) || valorSalario < 0) {
            return res.status(400).json({
                error: 'O salário deve ser um número válido e não negativo.'
            });
        }

        const [result] = await db.execute(
            `UPDATE funcionarios
             SET nome = ?, funcao = ?, salario = ?
             WHERE id = ?`,
            [nome.trim(), funcao.trim(), valorSalario, id]
        );

        if (result.affectedRows === 0) {
            return res.status(404).json({
                error: 'Funcionário não encontrado.'
            });
        }

        res.json({ success: true });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// DELETE /api/funcionarios/:id - Excluir funcionário
app.delete('/api/funcionarios/:id', async (req, res) => {
    try {
        const id = Number(req.params.id);

        if (!Number.isInteger(id) || id <= 0) {
            return res.status(400).json({
                error: 'ID inválido.'
            });
        }

        const [result] = await db.execute(
            'DELETE FROM funcionarios WHERE id = ?',
            [id]
        );

        if (result.affectedRows === 0) {
            return res.status(404).json({
                error: 'Funcionário não encontrado.'
            });
        }

        res.json({ success: true });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// Iniciar servidor
const PORT = 3000;

app.listen(PORT, () => {
    console.log(`Servidor rodando em http://localhost:${PORT}`);
    console.log(
        'Endpoints: GET/POST /api/funcionarios e PUT/DELETE /api/funcionarios/:id'
    );
});
